"use client";

import { useState, useEffect } from 'react';
import { useAuth, useUser } from '@clerk/nextjs';

/**
 * AuthDebugger component for diagnosing Clerk authentication issues
 * This component displays detailed information about the current authentication state
 * and helps diagnose common issues with Clerk authentication.
 */
export default function AuthDebugger({ showDetails = false }) {
  const { isLoaded: isAuthLoaded, userId, sessionId } = useAuth();
  const { isLoaded: isUserLoaded, user } = useUser();
  const [isVisible, setIsVisible] = useState(showDetails);
  const [systemTime, setSystemTime] = useState(new Date());
  const [serverTime, setServerTime] = useState(null);
  const [timeDiff, setTimeDiff] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  // Fetch server time to check for clock skew
  useEffect(() => {
    const fetchServerTime = async () => {
      try {
        setLoading(true);
        const response = await fetch('/api/debug/server-time');
        if (!response.ok) {
          throw new Error(`Server returned ${response.status}: ${response.statusText}`);
        }
        const data = await response.json();
        setServerTime(new Date(data.serverTime));
        
        // Calculate time difference in seconds
        const clientTime = new Date();
        setSystemTime(clientTime);
        const diffInSeconds = Math.abs(Math.round((clientTime - new Date(data.serverTime)) / 1000));
        setTimeDiff(diffInSeconds);
        
        setLoading(false);
      } catch (err) {
        setError(err.message);
        setLoading(false);
      }
    };

    if (isVisible) {
      fetchServerTime();
      // Update every 10 seconds
      const interval = setInterval(fetchServerTime, 10000);
      return () => clearInterval(interval);
    }
  }, [isVisible]);

  if (!isVisible) {
    return (
      <button 
        onClick={() => setIsVisible(true)}
        className="fixed bottom-4 right-4 bg-yellow-600 text-white px-3 py-2 rounded-md text-sm shadow-lg hover:bg-yellow-700 transition-colors z-50"
      >
        Debug Auth
      </button>
    );
  }

  // Check for potential clock skew issues
  const hasClockSkew = timeDiff !== null && timeDiff > 5; // More than 5 seconds difference

  return (
    <div className="fixed bottom-0 right-0 w-full md:w-96 bg-gray-900 border border-gray-700 rounded-t-lg shadow-xl z-50 text-white overflow-hidden">
      <div className="flex justify-between items-center bg-gray-800 px-4 py-2">
        <h3 className="font-semibold">Authentication Debugger</h3>
        <button 
          onClick={() => setIsVisible(false)}
          className="text-gray-400 hover:text-white"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M14.293 5.293a1 1 0 011.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 011.414-1.414L10 8.586l4.293-4.293z" clipRule="evenodd" />
          </svg>
        </button>
      </div>
      
      <div className="p-4 space-y-4 max-h-96 overflow-y-auto">
        {/* Authentication Status */}
        <div>
          <h4 className="text-sm font-semibold text-gray-400 mb-1">Authentication Status</h4>
          <div className="bg-gray-800 p-3 rounded-md">
            <div className="flex justify-between">
              <span>Auth Loaded:</span>
              <span className={isAuthLoaded ? "text-green-400" : "text-yellow-400"}>
                {isAuthLoaded ? "Yes" : "Loading..."}
              </span>
            </div>
            <div className="flex justify-between">
              <span>User Loaded:</span>
              <span className={isUserLoaded ? "text-green-400" : "text-yellow-400"}>
                {isUserLoaded ? "Yes" : "Loading..."}
              </span>
            </div>
            <div className="flex justify-between">
              <span>Authenticated:</span>
              <span className={userId ? "text-green-400" : "text-red-400"}>
                {userId ? "Yes" : "No"}
              </span>
            </div>
          </div>
        </div>
        
        {/* Clock Skew Check */}
        <div>
          <h4 className="text-sm font-semibold text-gray-400 mb-1">Clock Skew Check</h4>
          <div className="bg-gray-800 p-3 rounded-md">
            {loading ? (
              <div className="text-center text-gray-400">Checking server time...</div>
            ) : error ? (
              <div className="text-red-400">{error}</div>
            ) : (
              <>
                <div className="flex justify-between">
                  <span>Browser Time:</span>
                  <span>{systemTime.toISOString()}</span>
                </div>
                <div className="flex justify-between">
                  <span>Server Time:</span>
                  <span>{serverTime ? serverTime.toISOString() : "Unknown"}</span>
                </div>
                <div className="flex justify-between">
                  <span>Time Difference:</span>
                  <span className={hasClockSkew ? "text-red-400" : "text-green-400"}>
                    {timeDiff !== null ? `${timeDiff} seconds` : "Unknown"}
                  </span>
                </div>
                {hasClockSkew && (
                  <div className="mt-2 text-red-400 text-sm">
                    <strong>Warning:</strong> Your system clock is out of sync with the server. 
                    This can cause authentication issues. Please synchronize your system clock.
                  </div>
                )}
              </>
            )}
          </div>
        </div>
        
        {/* User Details */}
        {isUserLoaded && user && (
          <div>
            <h4 className="text-sm font-semibold text-gray-400 mb-1">User Details</h4>
            <div className="bg-gray-800 p-3 rounded-md">
              <div className="flex justify-between">
                <span>User ID:</span>
                <span className="text-xs">{user.id}</span>
              </div>
              <div className="flex justify-between">
                <span>Email:</span>
                <span>{user.primaryEmailAddress?.emailAddress || "None"}</span>
              </div>
              <div className="flex justify-between">
                <span>Name:</span>
                <span>{user.fullName || "Not set"}</span>
              </div>
            </div>
          </div>
        )}
        
        {/* Session Info */}
        <div>
          <h4 className="text-sm font-semibold text-gray-400 mb-1">Session Info</h4>
          <div className="bg-gray-800 p-3 rounded-md">
            <div className="flex justify-between">
              <span>Session ID:</span>
              <span className="text-xs">{sessionId || "No active session"}</span>
            </div>
            <div className="flex justify-between">
              <span>Last Updated:</span>
              <span>{new Date().toLocaleTimeString()}</span>
            </div>
          </div>
        </div>
        
        {/* Troubleshooting Actions */}
        <div>
          <h4 className="text-sm font-semibold text-gray-400 mb-1">Troubleshooting</h4>
          <div className="space-y-2">
            <button 
              onClick={() => window.location.href = '/sign-in'}
              className="w-full bg-blue-600 hover:bg-blue-700 text-white py-2 px-4 rounded-md text-sm transition-colors"
            >
              Go to Sign In
            </button>
            <button 
              onClick={() => window.location.reload()}
              className="w-full bg-gray-700 hover:bg-gray-600 text-white py-2 px-4 rounded-md text-sm transition-colors"
            >
              Reload Page
            </button>
            {hasClockSkew && (
              <button 
                onClick={() => window.open('/debug/fix-system-time', '_blank')}
                className="w-full bg-red-600 hover:bg-red-700 text-white py-2 px-4 rounded-md text-sm transition-colors"
              >
                Fix System Clock
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
